import{_ as t,o,c as a,a2 as i}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Versioning","description":"","frontmatter":{},"headers":[],"relativePath":"release/versioning.md","filePath":"release/versioning.md"}'),r={name:"release/versioning.md"};function n(s,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h1><h2 id="the-scheme" tabindex="-1">The scheme <a class="header-anchor" href="#the-scheme" aria-label="Permalink to &quot;The scheme&quot;">​</a></h2><p>Since the v1.0.0 public release, version identifiers are <strong>SemVer</strong>: <code>1.0.0</code>, <code>2.0.0</code>, <code>2.1.0</code>, ... Before that, the engineering phase used work-package stage names (<code>WP-14-docs_release</code>, <code>WP-13-build_system</code>, ...) - the internal equivalent of a release train per feature set. Since v2.0.0 the tags are plain <code>v&lt;version&gt;</code> (<code>git tag v2.1.0</code>), and <code>WP-*</code> tags exist only in history.</p><p>Additionally every build carries:</p><ul><li><strong>Build number</strong> = the commit count (<code>git rev-list --count HEAD</code>) at build time <strong>plus the permanent +21 alignment offset</strong> (<code>OC_KERNEL_BUILD_OFFSET := 21</code> in the Makefile). The offset dates from v1.0.0: the published build ids had been baked from an engineering tree whose git history ran 21 commits longer than the public repo main (WP-14-docs_release shipped build 274 at public count 253), and the OTA update check compares build ids NUMERICALLY (BUG-0347) - so the public sequence must continue above the already-published 274. One-build-per-commit monotonicity is preserved: the v1.0.0 tag sits at public count 257 -&gt; build 278; v2.0.0 at count 281 -&gt; build 302.</li><li><strong>Version banner</strong> = the frozen <code>OC_RELEASE_VERSION ?=</code> literal in the Makefile (an explicit <code>OC_RELEASE_VERSION=</code> override still wins, which is how the E2E update test works) - baked into the kernel banner, uname, the OTA manifest and the ISO. Earlier builds derived it from <code>git describe --tags</code>; v1.0.0 froze it to a literal so the banner no longer depends on local git state.</li></ul><h2 id="what-the-numbers-mean-together" tabindex="-1">What the numbers mean together <a class="header-anchor" href="#what-the-numbers-mean-together" aria-label="Permalink to &quot;What the numbers mean together&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td><code>uname -a</code></td><td><code>Open Cube OS 2.1.0 x86_64</code></td><td>the running kernel&#39;s version</td></tr><tr><td>update.json</td><td><code>version: 2.1.0, build: &lt;n&gt;</code></td><td>the published manifest</td></tr><tr><td>Release tag</td><td><code>v2.1.0</code></td><td>the git tag the assets were built from</td></tr><tr><td>gh-pages</td><td>the same two numbers in the download page</td><td>the website mirrors the Release</td></tr></tbody></table><p>One release = one tag = one build number = one manifest = one set of SHA256s across local / Release / gh-pages / private mirror. The tag must point at a CI-green commit (2.1.0 release gate).</p><h2 id="compatibility-promises" tabindex="-1">Compatibility promises <a class="header-anchor" href="#compatibility-promises" aria-label="Permalink to &quot;Compatibility promises&quot;">​</a></h2><ul><li>Shell commands are never removed without a declared deletion register; additions are the norm. The v1.0.0 baseline of 233 commands is preserved whole: every one is mapped in the <code>INTERFACES.md</code> Part 1c compatibility contract (251 v2 command homes = 99 L0 + 133 SVC + 19 built-ins).</li><li>L1SVC op numbers are never renumbered; new ops append (17 categories / 158 ops at 2.1.0). The retired v1 numbered surface&#39;s fate is per-entry truth: <code>INTERFACES.md</code> Part 2c/2d.</li><li>The OTA package updates the kernel only; /etc volume contents carry forward.</li><li>SemVer from here on: breaking changes bump MAJOR, new commands or L1SVC ops bump MINOR, fixes bump PATCH.</li></ul><h2 id="choosing-the-next-version" tabindex="-1">Choosing the next version <a class="header-anchor" href="#choosing-the-next-version" aria-label="Permalink to &quot;Choosing the next version&quot;">​</a></h2><p>SemVer rules above; <code>build</code> = commit count + 21 on release day - never hand-picked.</p>',12)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
